{
  "tools": [
    {
      "name": "bridge_call",
      "title": "Native Call",
      "toolset": "bridge_helpers",
      "description": "Run any registered Bridge helper through the native connection. Use bridge_describe_handler first. Preserves the original play-mode guards and undo behaviour. Prefer dedicated native tools where available.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "Exact command from bridge_list_handlers."
          },
          "parameters": {
            "type": "object",
            "description": "The helper's JSON parameters; omit for helpers with no arguments."
          }
        },
        "required": [
          "command"
        ]
      }
    },
    {
      "name": "bridge_list_handlers",
      "title": "Native List Handlers",
      "toolset": "bridge_helpers",
      "description": "List the live Bridge helpers, their read-only status and their play-mode restrictions. Use bridge_describe_handler to inspect arguments, then bridge_read or bridge_call.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "bridge_scatter_props",
      "title": "Native Scatter Props",
      "toolset": "bridge_helpers",
      "description": "Scatter model props with a repeatable seed, optional ground snapping, rotation, scaling and grouping. Requires stopped play mode. Uses the existing Bridge helper's scene and undo behaviour.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "model": {
            "type": "string",
            "description": "Project-relative model path, as returned by asset_search."
          },
          "center": {
            "type": "string",
            "description": "World-space centre as x,y,z, in Source units."
          },
          "radius": {
            "type": "number",
            "description": "Finite, nonnegative scatter radius in Source units.",
            "default": 256
          },
          "count": {
            "type": "integer",
            "description": "Number of props, from 1 to 300.",
            "default": 10
          },
          "seed": {
            "type": "integer",
            "description": "Nonnegative seed for repeatable placement.",
            "default": 1
          },
          "snapToGround": {
            "type": "boolean",
            "description": "Trace downward to place each prop on the ground.",
            "default": true
          },
          "randomYaw": {
            "type": "boolean",
            "description": "Randomise each prop's yaw.",
            "default": true
          },
          "scaleMin": {
            "type": "number",
            "description": "Positive minimum scale.",
            "default": 1
          },
          "scaleMax": {
            "type": "number",
            "description": "Maximum scale, at least scaleMin.",
            "default": 1
          },
          "group": {
            "type": "boolean",
            "description": "Parent the props under a new group object.",
            "default": true
          },
          "name": {
            "type": "string",
            "description": "Name prefix for the created objects.",
            "default": "Prop"
          }
        },
        "required": [
          "model",
          "center"
        ]
      }
    },
    {
      "name": "bridge_simulate_input",
      "title": "Native Simulate Input",
      "toolset": "bridge_helpers",
      "description": "Simulate a named input action during play. Press lasts one frame; hold is reapplied every frame; release ends a hold. A zero-duration hold continues until released. Requires play mode.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "description": "Input action name, for example jump, attack1 or attack2."
          },
          "state": {
            "type": "string",
            "description": "press, hold or release.",
            "default": "press"
          },
          "durationMs": {
            "type": "number",
            "description": "Nonnegative hold duration in milliseconds; zero holds until release.",
            "default": 0
          }
        },
        "required": [
          "action"
        ]
      }
    },
    {
      "name": "camera_screenshot",
      "title": "Camera Screenshot",
      "toolset": "scene",
      "description": "Render a camera in the scene and return it as an image. Give any CameraComponent's id or its game object's id, or nothing for the scene's main camera. Works in edit and play mode - editor_camera_screenshot shows the editor viewport instead.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "camera": {
            "type": "string",
            "description": "A CameraComponent id or its game object's id. Empty uses the scene's main camera."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          },
          "includeUi": {
            "type": "boolean",
            "description": "Include any UI the camera renders.",
            "default": true
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "editor_status",
      "title": "Get Editor Status",
      "toolset": "editor",
      "description": "Get the current state of the editor - engine version, which project is open, the active scene and whether it has unsaved changes, whether play mode is running or paused, how many tools are registered, the directory paths that matter (logs, project code and assets), and the state of the code compiler. Check IsCompiling/LastCompileSucceeded here after editing code instead of relying on read_console - a successful compile can scroll out of view or be mistaken for the last failure you saw.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "EngineVersion": {
            "type": "string"
          },
          "Project": {
            "type": "string"
          },
          "ProjectTitle": {
            "type": "string"
          },
          "ActiveScene": {
            "type": "string"
          },
          "ActiveScenePath": {
            "type": "string"
          },
          "SceneHasUnsavedChanges": {
            "type": "boolean"
          },
          "IsPlaying": {
            "type": "boolean"
          },
          "IsPaused": {
            "type": "boolean"
          },
          "ToolCount": {
            "type": "integer"
          },
          "IsCompiling": {
            "type": "boolean"
          },
          "LastCompileSucceeded": {
            "type": "boolean"
          },
          "LastCompileErrors": {
            "type": "integer"
          },
          "Paths": {
            "type": "object",
            "properties": {
              "Engine": {
                "type": "string"
              },
              "Logs": {
                "type": "string"
              },
              "ProjectRoot": {
                "type": "string"
              },
              "ProjectSettings": {
                "type": "string"
              }
            },
            "required": []
          }
        },
        "required": []
      }
    },
    {
      "name": "get_component_type",
      "title": "Get Component Type",
      "toolset": "component",
      "description": "Documentation for a component type by name - its class name, display title, description, group, and every inspector property with title, description, type and read-only state. Matches exact names first, then substrings; multiple substring matches come back as a candidate list.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "The component's type name, e.g. 'ModelRenderer'. Case insensitive, substrings work."
          }
        },
        "required": [
          "name"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_create_game_object",
      "title": "Create Game Object",
      "toolset": "hammer",
      "description": "Put a game object in the open map - empty, from a prefab, and/or with components and their properties set in the same call. This is how s&box gameplay goes in a map. The user can undo the creation. Returns the new node, whose GameObject field is the object's guid.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name for the object. Empty uses the prefab's name, or 'GameObject'."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "prefab": {
            "type": "string",
            "description": "Prefab asset path to instantiate, from asset_search type:prefab."
          },
          "components": {
            "type": "object",
            "description": "Components to add, as a json object of type name to properties - e.g. {\"ModelRenderer\": {\"Model\": \"models/dev/box.vmdl\"}, \"BoxCollider\": {}}. get_component_type documents types and properties. A type the prefab already has gets its properties set instead."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "instance_status",
      "title": "Status",
      "toolset": "instance",
      "description": "Get this process's PID, kind, project, engine version, active scene, play state and session exchange directory. Files in the exchange directory are retained after disconnect.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "network_disconnect",
      "title": "Disconnect",
      "toolset": "network",
      "description": "Leave the current game. If we're the host and other players are connected, the game is handed to one of them first, which is how to exercise host migration from the editor. Check the spawned instance's log for \"Becoming the host\".",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "IsActive": {
            "type": "boolean"
          },
          "IsHost": {
            "type": "boolean"
          },
          "IsClient": {
            "type": "boolean"
          },
          "IsConnecting": {
            "type": "boolean"
          },
          "LocalId": {
            "type": "string"
          },
          "HostId": {
            "type": "string"
          },
          "Connections": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "IsHost": {
                  "type": "boolean"
                },
                "IsLocal": {
                  "type": "boolean"
                },
                "IsActive": {
                  "type": "boolean"
                },
                "IsConnecting": {
                  "type": "boolean"
                },
                "Ping": {
                  "type": "number"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "network_start_hosting",
      "title": "Start Hosting",
      "toolset": "network",
      "description": "Host a lobby from the editor. Enters play mode first if needed. Local instances spawned with network_spawn_instance join this lobby.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "IsActive": {
            "type": "boolean"
          },
          "IsHost": {
            "type": "boolean"
          },
          "IsClient": {
            "type": "boolean"
          },
          "IsConnecting": {
            "type": "boolean"
          },
          "LocalId": {
            "type": "string"
          },
          "HostId": {
            "type": "string"
          },
          "Connections": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "IsHost": {
                  "type": "boolean"
                },
                "IsLocal": {
                  "type": "boolean"
                },
                "IsActive": {
                  "type": "boolean"
                },
                "IsConnecting": {
                  "type": "boolean"
                },
                "Ping": {
                  "type": "number"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "open_scene",
      "title": "Open Scene",
      "toolset": "scenefile",
      "description": "Open a scene from the asset system and make it the active tab. Already open scenes are just brought to the front. Play mode has to be stopped first - play_start then runs this scene.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Scene asset path, like \"scenes/menu-main.scene\". asset_search finds them."
          }
        },
        "required": [
          "path"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Active": {
            "type": "string"
          },
          "ActivePath": {
            "type": "string"
          },
          "Open": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "perf_cpu",
      "title": "Cpu",
      "toolset": "perf",
      "description": "Main thread detail: frame pacing, what caps the frame rate (fps_max, vsync, display mode), time by category, and every named timing scope. Scopes nest, so they overlap - a category includes the scopes inside it.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "limit": {
            "type": "integer",
            "description": "How many scopes to return, biggest first. Default 30, max 200.",
            "default": 30
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "play_pause",
      "title": "Play Pause",
      "toolset": "play",
      "description": "Pause or resume the running game.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "paused": {
            "type": "boolean",
            "description": "True to pause, false to resume.",
            "default": true
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "IsPlaying": {
            "type": "boolean"
          },
          "IsPaused": {
            "type": "boolean"
          },
          "Scene": {
            "type": "string",
            "description": "The scene being played. Null when not playing."
          }
        },
        "required": []
      }
    },
    {
      "name": "play_start",
      "title": "Play Start",
      "toolset": "play",
      "description": "Start playing the current scene, like pressing the editor's play button. Startup errors land in the console - check read_console if things look wrong.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "IsPlaying": {
            "type": "boolean"
          },
          "IsPaused": {
            "type": "boolean"
          },
          "Scene": {
            "type": "string",
            "description": "The scene being played. Null when not playing."
          }
        },
        "required": []
      }
    },
    {
      "name": "play_stop",
      "title": "Play Stop",
      "toolset": "play",
      "description": "Stop playing and return to editing.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "IsPlaying": {
            "type": "boolean"
          },
          "IsPaused": {
            "type": "boolean"
          },
          "Scene": {
            "type": "string",
            "description": "The scene being played. Null when not playing."
          }
        },
        "required": []
      }
    },
    {
      "name": "ui_panel_dump",
      "title": "Panel Dump",
      "toolset": "ui",
      "description": "The panel tree with each panel's screen rect, like a browser's elements pane. Every panel comes back with a path, which is how the rest of these tools address it. UI only exists while the scene runs, so play_start first.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "panel": {
            "type": "string",
            "description": "Panel path like '0/3/1', or a selector like '.mainmenu button'. Empty starts at the roots."
          },
          "depth": {
            "type": "integer",
            "description": "How many levels of children to include. ChildCount says what's below the cut.",
            "minimum": 0,
            "maximum": 32,
            "default": 3
          },
          "styles": {
            "type": "boolean",
            "description": "Include the computed style. Every property that's set, so ask for one panel.",
            "default": false
          },
          "styleFilter": {
            "type": "string",
            "description": "Only computed properties whose name contains this, e.g. 'border' or 'font'."
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    }
  ],
  "total": 128
}
